// Public, already-observed Claude Code state; only a live Codexio receiver gets it.
const config = __CODEXIO_CONFIG__;
let timer = null;
let sending = false;
let pending = null;
let last = null;
const contexts = new Map();
async function runtimeState($) {
  if (!(await $.fs.exists(config.runtime))) return null;
  const runtime = JSON.parse(await $.fs.read(config.runtime));
  return runtime.url && runtime.nonce && runtime.url.startsWith('http://127.0.0.1:') ? runtime : null;
}
async function deliver($, usage, scheduled = false, contextId = '') {
  try {
    const runtime = await runtimeState($);
    if (!runtime) return false;
    const now = await $.clock.now();
    const session = await $.session.id();
    const surfaces = await $.session.surfaces();
    const surface = surfaces.includes('desktop') ? 'desktop' : 'cli';
    const window = usage?.context?.window;
    if (contextId && typeof window === 'number' && Number.isSafeInteger(window) && window > 0) {
      const key = session + ':' + contextId;
      if (contexts.get(key)?.window !== window) contexts.set(key, {session_id:session,message_uuid:contextId,window,observed_at:now/1000});
      while (contexts.size > 32) contexts.delete(contexts.keys().next().value);
    }
    const windows = (usage?.rateLimits ?? []).filter(w => ['five_hour','seven_day'].includes(w.kind))
      .filter(w => typeof w.percentUsed === 'number' && Number.isFinite(w.percentUsed) && w.percentUsed >= 0 && w.percentUsed <= 100)
      .map(w => ({kind:w.kind,percentUsed:w.percentUsed,resetsAt:typeof w.resetsAt === 'string' ? w.resetsAt : null}));
    const points = [...contexts.values()];
    const signature = JSON.stringify([session,windows,points,runtime.nonce]);
    if (!scheduled && last && last.signature === signature && now >= last.time && now-last.time < 60000) return true;
    scheduled = scheduled || Boolean(pending?.payload?.scheduled && now-pending.time <= 5000);
    pending = {runtime,payload:{schema:1,source:'mods',surface,session_id:session,config_root:config.root,captured_at:now/1000,scheduled,windows,contexts:points},signature,time:now};
    if (sending) return true;
    sending = true;
    let ok = true;
    try {
      while (pending) {
        const value = pending; pending = null;
        const result = await $.http.fetch(value.runtime.url,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+value.runtime.nonce},body:JSON.stringify(value.payload)});
        ok = result.ok;
        if (ok) last = {signature:value.signature,time:value.time};
      }
    } finally {sending = false;}
    return ok;
  } catch {return false;}
}
async function readCurrent($, scheduled = false, contextId = '') {
  try {
    if (!(await runtimeState($))) return false;
    return await deliver($,await $.session.usage(),scheduled,contextId);
  } catch {return false;}
}
async function schedule($) {
  if (timer) return;
  try {
    if (!(await runtimeState($))) return;
    const now = await $.clock.now();
    // Read live engine state on minute boundaries, without model/API requests.
    timer = $.clock.after(Math.max(1,60000-now%60000),() => {void pulse($);});
  } catch {}
}
async function pulse($) {
  timer = null;
  if (await readCurrent($,true)) await schedule($);
}
export const register = on => {
  on('session.start',async ($,e,next) => {await readCurrent($);await schedule($);return next(e);});
  on('session.measure',async ($,e,next) => {await deliver($,e);await schedule($);return next(e);});
  on('session.append',async ($,e,next) => {
    const result = await next(e);
    if (!e.agentId && ['prompt','response'].includes(e.door) && !e.message.isMeta) {
      const uuid = result.uuid ?? e.uuid;
      await readCurrent($,false,uuid);await schedule($);
    }
    return result;
  });
  on('turn.start',async ($,e,next) => {await readCurrent($);await schedule($);return next(e);});
  on('turn.complete',async ($,e,next) => {if (!e.agentId) await readCurrent($);await schedule($);return next(e);});
  on('session.end',async ($,e,next) => {if (timer) timer.cancel();timer=null;contexts.clear();return next(e);});
};
